 public class City {
    private String name;
    private double population;

    public City(String name, double population) {
        this.name = name;
        this.population = population;
    }

    public String getName() {
        return this.name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public double getPopulation() {
        return this.population;
    }

    public void setPopulation(double population) {
        this.population = population;
    }
}

public class Market {
    public static void main(String[] args) {
        // Create some cities with their populations
        City city1 = new City("City A", 1000000);
        City city2 = new City("City B", 500000);
        City city3 = new City("City C", 200000);

        // Print the names and populations of the cities
        System.out.println(city1.getName() + " has a population of " + city1.getPopulation());
        System.out.println(city2.getName() + " has a population of " + city2.getPopulation());
        System.out.println(city3.getName() + " has a population of " + city3.getPopulation());

        // Update the populations of the cities
        city1.setPopulation(1200000);
        city2.setPopulation(600000);
        city3.setPopulation(250000);

        // Print the updated populations
        System.out.println("\nAfter update:");
        System.out.println(city1.getName() + " has a population of " + city1.getPopulation());
        System.out.println(city2.getName() + " has a population of " + city2.getPopulation());
        System.out.println(city3.getName() + " has a population of " + city3.getPopulation());
    }
}
