#define NO_VALUE -1

const int PRIMARY[3][3] = { {1, 0, 1}, {0, 1, 1}, {0, 1, 1} };

// Basic mathematicalexpressions:
double evaluate(int x, int y) {
    if (x < 0 || x > MAX_ROWS || y < 0 || y > MAX_COLS) {
        cout << "out of bound, you have entered wrong range for x,y values." << endl;
        return -1;
    }

    // Interpolate from constant arrays
    int keyVal = PRIMARY[x][y];
    double val = 0;

    if (keyVal == PRIMARY[0][0]) {
        val = static_cast<double>(x + y);
    }
    else if (keyVal == PRIMARY[0][1]) {
        val = static_cast<double>(x * y);
    }
    else if (keyVal == PRIMARY[0][2]) {
        val = static_cast<double>((x + y) / 2);
    }
    else if (keyVal == PRIMARY[1][0]) {
        val = static_cast<double>(x % y);
    }
    else if (keyVal == PRIMARY[1][1]) {
        val = static_cast<double>(x / y);
    }
    else if (keyVal == PRIMARY[1][2]) {
        val = static_cast<double>(x & y);
    }
    else if (keyVal == PRIMARY[2][0]) {
        val = static_cast<double>(x ^ y);
    }
    else if (keyVal == PRIMARY[2][1]) {
        val = static_cast<double>(x | y);
    }
    else if (keyVal == PRIMARY[2][2]) {
        val = static_cast<double>(x >> y);
    }

    return val;
}

void showEval(int x, int y) {
    cout << "\nx:" << x << ", y:" << y << endl;
    double res = evaluate(x, y);

    if (res >= 0)
        cout << "RESULT = " << res << endl;
    else {
        cout << "ERROR";
    }
}

// Helper to add front
struct node {
    int data;
    struct node* next;
};

struct node* insertFront(struct node* head, int x) {
    struct node* new_node = new struct node();
    new_node->data = x;
    new_node->next = head;
    return new_node;
}

// Helper to delete rear
struct node* removeBack(struct node* head) {
    if (!head) return NULL;

    struct node* current = head;
    if (!current->next) {
        delete current;
        return NULL;
    }

    while (current->next->next) {
        current = current->next;
    }

    struct node* temp = current->next;
    current->next = NULL;
    delete temp;
    return head;
}

// Helper to print linked list
void printList(struct node* head) {
    if (!head) {
        cout << "List is empty.\n";
        return;
    }

    struct node* current = head;
    while (current != NULL) {
        cout << current->data << " -> ";
        current = current->next;
    }
    cout << "NULL\n";
}

int main() {
    // Create a sample linked list
    struct node* head = NULL;
    head = insertFront(head, 5);
    head = insertFront(head, 4);
    head = insertFront(head, 3);
    head = insertFront(head, 2);
    head = insertFront(head, 1);

    // Print the initial list
    cout << "Initial List:\n";
    printList(head);

    // Remove the last element
    head = removeBack(head);
    cout << "After removing the last element:\n";
    printList(head);

    // Test evaluation
    showEval(2, 3); // Should be 2 + 3 = 5, but according to PRIMARY logic? Let's see

    return 0;
}
